import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { signOut } from "firebase/auth";
import { auth } from "../lib/firebase";
import { getAllBlogs, deleteBlog, createBlog, updateBlog } from "../services/blogService";
import type { Blog } from "../types/blog";
import BlogModal from "../components/BlogModal";

const AdminBlog = () => {
  const navigate = useNavigate();
  const [blogs, setBlogs] = useState([]);
  const [loading, setLoading] = useState(true);


  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingBlog, setEditingBlog] = useState(null);

  const fetchBlogs = async () => {
    try {
      setLoading(true);
      const data = await getAllBlogs();
      setBlogs(data);
    } catch (error) {
      console.error("Gagal mengambil data blog:", error);
      alert("Gagal mengambil data blog dari server.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchBlogs();
  }, []);

  const handleLogout = async () => {
    try {
      await signOut(auth);
      navigate("/login");
    } catch (error) {
      console.error("Gagal logout:", error);
    }
  };

  const handleDelete = async (id?: string) => {
    if (!id) return;
    const confirmDelete = window.confirm("Apakah Anda yakin ingin menghapus blog ini?");
    if (!confirmDelete) return;

    try {
      await deleteBlog(id);
      setBlogs(blogs.filter(blog => blog.id !== id));
    } catch (error) {
      console.error("Gagal menghapus blog:", error);
      alert("Gagal menghapus blog.");
    }
  };

  const handleAddClick = () => {
    setEditingBlog(null);
    setIsModalOpen(true);
  };

  const handleEditClick = (blog: Blog) => {
    setEditingBlog(blog);
    setIsModalOpen(true);
  };

  const handleModalSubmit = async (data: Omit) => {
    try {
      if (editingBlog && editingBlog.id) {
        await updateBlog(editingBlog.id, data);
      } else {
        await createBlog(data);
      }
      fetchBlogs();
    } catch (error) {
      console.error("Error saving data:", error);
      throw error;
    }
  };

  return (







Manajemen Blog

            Logout








Daftar Blog

              + Tambah Blog Baru



          {loading ? (

Memuat data...
          ) : blogs.length === 0 ? (


              Belum ada artikel blog.

          ) : (






                    Foto
                    Judul
                    Tampil di Depan
                    Tanggal Dibuat
                    Aksi



                  {blogs.map((blog) => (







{blog.nama}

{blog.deskripsi}



                          {blog.ditampilkan_di_landing_page ? 'Ya' : 'Tidak'}



                        {new Date(blog.createdAt).toLocaleDateString('id-ID')}


                         handleEditClick(blog)}
                        >
                          Edit

                         handleDelete(blog.id)}
                        >
                          Hapus



                  ))}



          )}



       setIsModalOpen(false)}
        onSubmit={handleModalSubmit}
        initialData={editingBlog}
      />

  );
};

export default AdminBlog;

